$arr = [100, 60, 30, 22, 1];

function scale(array $array, float $min, float $max): array
{
    $lowest = min($array);
    $highest = max($array);

    return array_map(function ($elem) use ($lowest, $highest, $min, $max) {
        return ($max - $min) * ($elem - $lowest) / ($highest - $lowest) + $min;
    }, $array);
}

